; VEGETA module: Joch's trial in the Hyperbolic Time Chamber.
; Port of engine/joch-trial.js, engine/time-chamber.js, engine/vegeta-sprite.js,
; engine/vegeta-clash.js and engine/beam-detonation.js (the cues of
; engine/vegeta-arrangement.js belong to the audio module).
; See docs/agents/snes-port/vegeta.md.
;
; Resources:
;   code  !CODE_VEGETA ($A8:8000-FFFF); $A8:F000-FFFF bind.asm (bindings to
;         optional modules, assembled after every module)
;   data  !DATA_VEGETA ($E8:0000-7FFF): chamber metatiles, grid, palettes,
;         Vegeta's frame table; generated by snes/gen/vegeta.mjs
;   art   $F4:0000-7FFF chamber BG tiles + Vegeta OBJ blocks
;   WRAM  !RAM_VEGETA ($7E:DBC0, $40 bytes): hot trial state
;   SRAM  !SRAM_WORK_SCENE ($32:6000-$32:63FF) while the trial runs
;
; Conventions: routines run with M16/X16, DB = $7E, D = 0 unless noted;
; immediates carry .b/.w (asar does not track REP/SEP).

incsrc "vegeta/chamber_gen.asm"

; ---------------------------------------------------------------------------
; WRAM (!RAM_VEGETA = $7E:DBC0, $40 bytes). Absolute addresses (DB = $7E).
!VG = $DBC0
assert !RAM_VEGETA == $7E0000|!VG, "!VG must match !RAM_VEGETA"
!vg_on          #= !VG+$00   ; byte: !VG_ON while a trial state exists (browser `s`)
!vg_phase       #= !VG+$01   ; byte: !VP_* (intro, battle, transform, draw)
!vg_flags       #= !VG+$02   ; byte: !VF_*
!vg_mask        #= !VG+$03   ; byte: party mask borrowed by the trial (bit0 girl, bit1 sprite)
!vg_tier        #= !VG+$04   ; byte: 0 base, 1 Super Saiyan
!vg_facing      #= !VG+$05   ; byte: 0 down, 1 right, 2 left, 3 up
!vg_hp          #= !VG+$06   ; word
!vg_x           #= !VG+$08   ; word: map pixels (feet)
!vg_y           #= !VG+$0A   ; word
!vg_terrain     #= !VG+$0C   ; byte: native terrain byte ($E60B)
!vg_hurt        #= !VG+$0D   ; byte: hit flash/recoil frames
!vg_age         #= !VG+$0E   ; word: battle frames
!vg_clock       #= !VG+$10   ; word (signed): frames to the next attack
!vg_grace       #= !VG+$12   ; word: frames Goku cannot be hurt
!vg_phase_age   #= !VG+$14   ; word
!vg_cycle       #= !VG+$16   ; byte: attack cycle index
!vg_melee       #= !VG+$17   ; byte: melee hits in a row
!vg_last_melee  #= !VG+$18   ; word: age of the last melee hit
!vg_travel      #= !VG+$1A   ; word: pixels walked (walk cycle)
!vg_moving_until #= !VG+$1C  ; word: age until which he counts as moving
!vg_backstep    #= !VG+$1E   ; byte: last step went backwards
!vg_quips       #= !VG+$1F   ; byte: wall remarks made
!vg_act         #= !VG+$20   ; byte: !VA_* current action, 0 none
!vg_act_dx      #= !VG+$21   ; byte (signed) direction of the action
!vg_act_dy      #= !VG+$22   ; byte (signed)
!vg_arrival     #= !VG+$23   ; byte: s.arrival
!vg_act_age     #= !VG+$24   ; word
!vg_act_x       #= !VG+$26   ; word: origin (beam / volley origin)
!vg_act_y       #= !VG+$28   ; word
!vg_contact     #= !VG+$2A   ; word: age of first contact, $FFFF none
!vg_music       #= !VG+$2C   ; byte: music cue last sent (0 native, 1 vegeta, 2 full power)
!vg_cwin        #= !VG+$2D   ; byte: 1 while combat's step sees him in slot 3 (bind.asm)
!vg_spare2e     #= !VG+$2E   ; byte (free)
!vg_clash_on    #= !VG+$2F   ; byte: a clash is running (state in SRAM)
; sprite / VRAM double buffer (also read by the NMI routine)
!vg_front       #= !VG+$30   ; byte: frame shown from the front buffer ($FF none)
!vg_back        #= !VG+$31   ; byte: frame held by the back buffer ($FF none)
!vg_front_buf   #= !VG+$32   ; byte: which buffer is the front (0 A, 1 B)
!vg_want        #= !VG+$33   ; byte: frame requested for the back buffer ($FF none)
!vg_echo_frame  #= !VG+$34   ; byte: frame in the echo area ($FF none)
!vg_echo_want   #= !VG+$35   ; byte
!vg_pal_flash   #= !VG+$36   ; byte: palette written last (0 colours, 1 white)
!vg_misc        #= !VG+$37   ; byte: bit0 combat danger set, bit1 input lock held, bit2 locks held
!vg_t0          #= !VG+$38   ; scratch words $38-$3F (call-local)
!vg_t1          #= !VG+$3A
!vg_t2          #= !VG+$3C
!vg_t3          #= !VG+$3E
!VG_END         = !VG+$40

!VG_ON = $5A
!VP_INTRO     = 0
!VP_BATTLE    = 1
!VP_TRANSFORM = 2
!VP_DRAW      = 3
!VF_SPAWNED   = $01
!VF_INTRODUCED = $02
!VF_REVEALED  = $04
!VF_COMPLETE  = $08         ; entrance finished (brightness settled)
!VF_DRAW      = $10         ; finish(true): a draw (else Goku needed a break)
!VF_WON       = $20
!VF_RETURNING = $40
!VF_EARLY_SSJ = $80         ; "Super Saiyan already?" said
!VA_RUSH    = 1
!VA_VOLLEY  = 2
!VA_BEAM    = 3
!VA_COUNTER = 4

; ---------------------------------------------------------------------------
; SRAM (!SRAM_WORK_SCENE, long addressing): the rest of the trial state.
; Valid only while !vg_on = !VG_ON (the scene buffer is shared by the set
; pieces one scene at a time; the trial initialises it in vegeta_start).
!VS #= !SRAM_WORK_SCENE
!vs_view        #= !VS+$000  ; 4 words: hero x, hero y, $A8, $AA last frame (entrance)
!vs_view_ok     #= !VS+$008  ; byte
!vs_beam_on     #= !VS+$009  ; byte: the action's beam exists (a.beam)
!vs_tx          #= !VS+$00A  ; word: action target (hero at begin)
!vs_ty          #= !VS+$00C  ; word
!vs_beam_x      #= !VS+$00E  ; word: beam origin
!vs_beam_y      #= !VS+$010  ; word
!vs_beam_len    #= !VS+$012  ; word
!vs_beam_half   #= !VS+$014  ; word
!vs_rand        #= !VS+$016  ; word (unused by the browser logic; reserved)
!vs_shots       #= !VS+$020  ; !VS_SHOTS x 8: x, y (words), dx, dy (bytes), speed, age (bytes; age $FF = free)
!VS_SHOTS = 8
!vs_bursts      #= !VS+$060  ; !VS_BURSTS x 6: x, y, age (words; age $FFFF free)
!VS_BURSTS = 10
!vs_rocks       #= !VS+$0A0  ; !VS_ROCKS x 6: x, y, age (words; age $FFFF free)
!VS_ROCKS = 6
!vs_echoes      #= !VS+$0C4  ; !VS_ECHOES x 8: x, y, age (words), frame, flip (bytes)
!VS_ECHOES = 4
!vs_gb_age1     #= !VS+$0E4  ; word: vb_combat_beam scratch (age + 1)
!vs_gb_life     #= !VS+$0E6  ; word
!vs_gb_cap      #= !VS+$0E8  ; word
!vs_hit_amount  #= !VS+$0EA  ; word: vg_hit's arguments (amount, flags)
!vs_hit_flags   #= !VS+$0EC  ; word
; nonzero while a list may hold live records (set on add, recounted by
; its update): empty lists are skipped by the draw and the update
!vs_live_shots  #= !VS+$0EE  ; byte
!vs_live_bursts #= !VS+$0EF  ; byte
!vs_live_rocks  #= !VS+$0F0  ; byte
!vs_live_echoes #= !VS+$0F1  ; byte
!vs_step_inc    #= !VS+$0FC  ; word: vg_step_dir's |dx| + |dy|
!vs_step_back   #= !VS+$0FE  ; byte: vg_step_dir's backstep
!vs_clash       #= !VS+$100  ; clash record (clash.asm)
; drawing scratch (sprite.asm)
!vs_draw_frame  #= !VS+$180  ; word
!vs_draw_x      #= !VS+$182  ; word: anchor screen x
!vs_draw_y      #= !VS+$184  ; word: anchor OAM y
!vs_draw_n      #= !VS+$186  ; word: blocks of the frame
!vs_draw_ptr    #= !VS+$188  ; word: offsets pointer
!vs_draw_i      #= !VS+$18A  ; word: block index
!vs_draw_tile   #= !VS+$18C  ; word: first tile of the buffer drawn
!vs_draw_attr   #= !VS+$18E  ; word: OAM bytes 2-3 bits besides the tile (palette, priority, flip)
!vs_draw_front  #= !VS+$190  ; word: 1 in front of the natives, 0 behind
!vs_cam_x       #= !VS+$192  ; word: camera of this frame's drawing
!vs_cam_y       #= !VS+$194  ; word
; pickSpot scratch
!vs_p_dir       #= !VS+$196
!vs_p_dist      #= !VS+$198
!vs_p_cx        #= !VS+$1B0
!vs_p_cy        #= !VS+$1B2
!vs_p_fd        #= !VS+$1B4
!vs_p_fx        #= !VS+$1B6
!vs_p_fy        #= !VS+$1B8
!vs_p_ad        #= !VS+$1BA
!vs_p_ax        #= !VS+$1BC
!vs_p_ay        #= !VS+$1BE
; misc state
!vs_damage      #= !VS+$1C0  ; word: s.damageTaken (diagnostics)
!vs_stable      #= !VS+$1C2  ; byte: entrance frames the view stayed still
!vs_clashes     #= !VS+$1C3  ; byte: clashes started (diagnostics)
!vs_counters    #= !VS+$1C6  ; byte: counters started (diagnostics)
!vs_flash_beam  #= !VS+$1C4  ; word: !vg_act_age of the beam's Final Flash call
; Goku's live beam (bind.asm vb_goku_beam): palms, direction, length,
; half width (8.8), fired as Super Saiyan, full wave (taper 44)
!vs_gb_x        #= !VS+$1D0
!vs_gb_y        #= !VS+$1D2
!vs_gb_dx       #= !VS+$1D4
!vs_gb_dy       #= !VS+$1D6
!vs_gb_len      #= !VS+$1D8
!vs_gb_half     #= !VS+$1DA
!vs_gb_super    #= !VS+$1DC  ; byte
!vs_gb_mega     #= !VS+$1DD  ; byte
; test stand-in for Goku's beam (same layout), used without combat_api_beam
!vs_tb_x        #= !VS+$1E0
!vs_tb_on       #= !VS+$1F0  ; byte
; logs for tests: last sound (id, tick), telepathy line (id, tick), music cue
!vs_log_sfx     #= !VS+$1F2
!vs_log_say     #= !VS+$1F6
!vs_log_song    #= !VS+$1FA
; test mailbox (VEGETA_TEST builds): command, arguments
!vs_dbg_cmd     #= !VS+$1FC  ; byte: 1 = hit(!vs_dbg_a, melee !vs_dbg_b bit0)
!vs_dbg_n       #= !VS+$1FD  ; byte: commands run
!vs_dbg_a       #= !VS+$200
!vs_dbg_b       #= !VS+$202
; logic scratch (trial.asm; call-local)
!vs_s0          #= !VS+$1A0
!vs_s1          #= !VS+$1A2
!vs_s2          #= !VS+$1A4
!vs_s3          #= !VS+$1A6
!vs_s4          #= !VS+$1A8
!vs_s5          #= !VS+$1AA
!vs_s6          #= !VS+$1AC
!vs_s7          #= !VS+$1AE
!vs_end         #= !VS+$200   ; cleared by vegeta_start (the mailbox args above it are not)
; slot 3 bytes held while combat's step sees Vegeta there (bind.asm)
!vs_cw_e600     #= !VS+$204  ; byte: flags
!vs_cw_species  #= !VS+$205  ; byte
!vs_cw_e7f0     #= !VS+$206  ; byte
!vs_cw_e7ec     #= !VS+$207  ; byte
; test log (VEGETA_TEST builds; snes/test/vegeta/replay.mjs): every hit
; (mailbox or combat) as a ring of 4 x 32 bytes at !vs_hl indexed by
; !vs_dbg_n: +0 damage, +2 flags (bit0 melee, bit1 combat beam record,
; bit2 from the mailbox),
; +4 combat's beam record (16 bytes), +20 charge, +22 range, +24 speed.
; !vs_tk: the beam record as the tick saw it (+2 flags, +4.. as above).
!vs_hl          #= !VS+$210
!vs_tk          #= !VS+$290
!vs_log_pose    #= !VS+$2B0  ; frame drawn this field frame ($FF none), recoil dx, dy
!vs_log_end     #= !VS+$2B4
assert (!vs_echoes+(!VS_ECHOES*8)) <= !vs_clash, "vegeta SRAM layout overlap"

; Sound cues (the audio module's !AUDIO_SFX_* ids; bind.asm asserts them)
!VSFX_HIT                = 3
!VSFX_BLAST              = 5
!VSFX_IMPACT             = 6
!VSFX_CHARGED            = 9
!VSFX_TRANSFORM          = 10
!VSFX_REVERT             = 11
!VSFX_POWER_BURST        = 12
!VSFX_DEFLECT            = 13
!VSFX_TELEPORT           = 16
!VSFX_TELEPORT_IN        = 17
!VSFX_FLIGHT             = 18
!VSFX_FRIEZA_IMPACT      = 24
!VSFX_FORTRESS_BREAK     = 25
!VSFX_VEGETA_BEAM        = 27
!VSFX_VEGETA_FINAL_FLASH = 29
!VSFX_VEGETA_KAKAROT     = 30
!VSFX_CHARGE             = 0     ; 'charge' is a loop cue: playSound() ignores it
; Telepathy lines (joch-trial.js radio.say / interrupt, source order)
!VMSG_FINAL_FLASH = 0
!VMSG_PUSH_BACK   = 1
!VMSG_DOORWAY     = 2
!VMSG_NOT_BAD     = 3
!VMSG_EARLY_SSJ   = 4
!VMSG_NOW_TALKING = 5
!VMSG_DRAW_1      = 6
!VMSG_REST_1      = 7
!VMSG_DRAW_2      = 8
!VMSG_REST_2      = 9

; Story hooks/queries implemented here (story/hooks.asm picks them up).
; (Story test builds bind them to their own stubs first: keep those.)
if not(defined("STORY_HOOK_TRIAL_START"))
	!STORY_HOOK_TRIAL_START = vegeta_story_trial_start
endif
if not(defined("STORY_QUERY_TRIAL_ACTIVE"))
	!STORY_QUERY_TRIAL_ACTIVE = vegeta_q_trial_active
endif
if not(defined("STORY_QUERY_TRIAL_PARTY"))
	!STORY_QUERY_TRIAL_PARTY = vegeta_q_trial_party
endif

; Goku's attacks on Vegeta: combat's per-hit damage hook (bind.asm
; vegeta_combat_damage) owns slot 3 while the trial runs and hands every
; other actor to the hook bound before this module, if any.
if defined("COMBAT_HOOK_DAMAGE")
	!VEGETA_DAMAGE_NEXT := !COMBAT_HOOK_DAMAGE
endif
!COMBAT_HOOK_DAMAGE = vegeta_combat_damage
; slot 3's species while combat's step sees him: a boss's (>= 84, not the
; orb $55), so no launch moves him (mana-mod.js hit(): custom foes return
; before the knockback)
!VEGETA_CW_SPECIES = 84

; Vegeta's OBJ VRAM (sprite.asm): buffers A/B and the echo, first tiles
!VGB_A_TILE = $080
!VGB_B_TILE = $0E0
!VGB_E_TILE = $068
!VGB_E4_TILE = $0C8

; The clash ball (ball.asm): OBJ VRAM buffers, palette, SRAM state
!VBALL_A_TILE = $0A0
!VBALL_B_TILE = $100
!VBALL_PAL = 5
!vs_ball_front #= !VS+$1C8      ; byte: radius in the front buffer (0 none)
!vs_ball_back  #= !VS+$1C9      ; byte
!vs_ball_want  #= !VS+$1CA      ; byte
!vs_ball_buf   #= !VS+$1CB      ; byte: 0 A front, 1 B front
!vs_ball_cx    #= !VS+$1CC      ; word: centre (map)
!vs_ball_cy    #= !VS+$1CE      ; word

; Constants from engine/joch-trial.js
!VEGETA_HP0 = 32000
!VEGETA_HP1 = 60000
!VEGETA_SPECIES = $2E          ; the boy's Doppelganger (actor slot 3, $E600)
!VEGETA_SLOT = $0600           ; actor offset of the slot Vegeta occupies
!VEGETA_OBJ_PAL = 4            ; OBJ palette (the Doppelganger's own)
!VEGETA_OWNER = $08            ; owner bit for combat locks

; ---------------------------------------------------------------------------
; Generated data
pushpc
org !DATA_VEGETA
vegeta_chamber_meta:
incbin "vegeta/chamber_meta.bin"
vegeta_chamber_pal:
incbin "vegeta/chamber_pal.bin"
vegeta_chamber_grid:
incbin "vegeta/chamber_grid.bin"
vegeta_pal:
incbin "vegeta/vegeta_pal.bin"
incsrc "vegeta/vegeta_gen.asm"
incsrc "vegeta/clash_gen.asm"
vegeta_data_end:
assert vegeta_data_end <= !DATA_VEGETA+$8000, "vegeta data bank overflow"
org $F40000
vegeta_chamber_tiles:
incbin "vegeta/chamber_tiles.bin"
vegeta_tiles:
incbin "vegeta/vegeta_tiles.bin"
vegeta_art_end:
assert vegeta_art_end <= $F48000, "vegeta art exceeds $F4:0000-7FFF"
org $F50000
vegeta_ball_tiles:
incbin "vegeta/clash_tiles.bin"
vegeta_art2_end:
assert vegeta_art2_end <= $F58000, "vegeta art exceeds $F5:0000-7FFF"
pullpc

; ---------------------------------------------------------------------------
; Code
pushpc
org !CODE_VEGETA
vegeta_code_start:
incsrc "chamber.asm"
incsrc "math.asm"
incsrc "trial.asm"
incsrc "ai.asm"
incsrc "attack.asm"
incsrc "clash.asm"
incsrc "draw.asm"
incsrc "ball.asm"
incsrc "sprite.asm"
vegeta_code_end:
assert vegeta_code_end <= !CODE_VEGETA+$7000, "vegeta code exceeds $A8:8000-EFFF"
pullpc
